class Solution {
    public: vector<int> rearrangeArray(vector<int>& nums) {
        map<int,int> f;
        int mx=0;
        for(int x:nums)mx=max(mx,++f[x]);
        vector<int> ans;
        for(int round=0; round<mx; round++)for(auto &p:f)if(p.second>round)ans.push_back(p.first);
        return ans;
    }
}
